    /** Android JSON coerces its explicit NULL sentinel to "null"; the pinned host JSON does not. */
    static final class AndroidNullStrings extends JSONObject {
        AndroidNullStrings(String raw)throws JSONException {super(raw);}
        @Override public String getString(String name)throws JSONException {return super.opt(name)==JSONObject.NULL?"null":super.getString(name);}
        @Override public String optString(String name){return optString(name,"");}
        @Override public String optString(String name,String fallback){return super.opt(name)==JSONObject.NULL?"null":super.optString(name,fallback);}
    }
